import { blockCrushDropDefinition as definition } from '../../nativeReference/games/block-crush-drop/definition';
import type { BlockCrushDropConfig } from '../../nativeReference/games/block-crush-drop/types';
import { readBCProject } from './document';

/** Small editable native example; all artwork and audio are generated by the studio. */
export function createBCDemo() {
  const colour = '#67c6be';
  const config: BlockCrushDropConfig = {
    columns: 10,
    rows: 16,
    initialCells: Array.from({ length: 10 }, (_, x) => x)
      .filter((x) => x !== 4 && x !== 5)
      .map((x) => ({ id: `base-${x}`, kind: colour, x, y: 0 }))
      .concat([0, 1, 8, 9].map((x) => ({ id: `upper-${x}`, kind: colour, x, y: 1 }))),
    pieces: [
      {
        id: 'domino',
        kind: colour,
        cells: [
          { x: 0, y: 0 },
          { x: 1, y: 0 },
        ],
        allowedQuarterTurns: [0],
      },
      { id: 'single', kind: colour, cells: [{ x: 0, y: 0 }], allowedQuarterTurns: [0] },
      {
        id: 'triple',
        kind: colour,
        cells: [
          { x: 0, y: 0 },
          { x: 1, y: 0 },
          { x: 2, y: 0 },
        ],
        allowedQuarterTurns: [0],
      },
    ],
    trayBatches: Array.from({ length: 8 }, () => [
      { pieceId: 'domino', quarterTurns: 0 as const },
      { pieceId: 'single', quarterTurns: 0 as const },
      { pieceId: 'triple', quarterTurns: 0 as const },
    ]),
    rules: {
      pieceSource: 'three-slot-tray',
      placement: 'tray-drag-release-then-vertical-fall',
      rotation: 'fixed-from-tray',
      clear: 'newly-completed-horizontal-rows',
      gravity: 'vertical-after-release',
      settlement: 'retained-piece-cascade',
      collapse: 'compact-rows-above-clear',
      fieldMotion: {
        kind: 'continuous-rise',
        ticksPerCell: 480,
        incomingRows: Array.from({ length: 8 }, () => '1111001111'),
      },
      scoring: {
        placedCell: 1,
        eliminatedCell: 5,
        successiveClearMultiplier: 0.5,
        chainMultiplier: 1,
      },
    },
    presentation: {
      layout: 'top-queue-full-height',
      tile: 'embossed-star',
      hud: 'timer-score-queue',
      referenceCalibration: {
        version: 1,
        background: '#12262d',
        material: 'bevel',
        tileColor: colour,
        board: {
          x: 130,
          y: 350,
          cell: 82,
          background: '#132f37',
          line: '#23434c',
          horizontalLines: true,
        },
        hud: {
          kind: 'score',
          height: 100,
          background: '#12262d',
          color: '#e4f7f3',
          levelLabel: '',
          level: '',
          scoreLabel: 'SCORE',
          initialScore: 0,
          countdown: 0,
        },
        queue: { visible: true, y: 170, scale: 0.48 },
        bevel: 0.1,
        seam: 0.025,
        shadow: 0.2,
        clear: {
          style: 'granular-sweep',
          subdivisions: 3,
          frontSeconds: 0.35,
          fallPixels: 1800,
          scatterPixels: 90,
          lifetimeSeconds: 1.4,
          fragmentGeometry: 'faceted-chip',
          fragmentScale: 1.2,
          fragmentShading: 'material',
          fragmentMaterialTexture: false,
        },
      },
    },
  };
  const state = definition.runtime.createInitialState(config, 1);
  const stateHash = definition.runtime.hashState(state);
  return readBCProject({
    format: 'bcs-studio-project',
    version: '2.0.0',
    id: 'bc-showcase',
    name: '青屿 · 落消示例',
    game: {
      contract: 'bcs.game-project',
      contractVersion: '1.0.0',
      game: {
        id: 'block-crush-drop',
        moduleVersion: '0.4.0',
        rulesetId: 'block-crush-drop-tray-drag-rising-cuts-v1',
        rulesetVersion: '1.0.0',
      },
      config: { schemaId: definition.schemas.config.id, data: config },
      initialState: { schemaId: definition.schemas.state.id, data: state, stateHash },
    },
    production: {
      layoutProfileRef: {
        id: 'block-crush-drop.layout.top-queue-full-height',
        version: '1.0.0',
        kind: 'ui-theme',
      },
      cameraProfileRef: {
        id: 'block-crush-drop.camera.fixed.v1',
        version: '1.0.0',
        kind: 'camera-profile',
      },
      lookPackRef: {
        id: 'block-crush-drop.look.crushzr29976-procedural.v2',
        version: '2.0.0',
        kind: 'look-pack',
      },
      output: { width: 540, height: 960, fps: 30, quality: 'preview' },
    },
    takes: [
      {
        contract: 'bcs.game-replay',
        contractVersion: '1.0.0',
        gameId: 'block-crush-drop',
        moduleVersion: '0.4.0',
        takeId: 'demo',
        initialStateHash: stateHash,
        seed: 1,
        actions: [
          { traySlot: 0, impactTick: 30, release: { x: 4, y: 15 } },
          { traySlot: 1, impactTick: 75, release: { x: 3, y: 15 } },
          { traySlot: 2, impactTick: 120, release: { x: 5, y: 15 } },
        ].map((action, i) => ({
          id: `demo-${i + 1}`,
          actor: 'agent',
          schemaId: definition.schemas.action.id,
          action,
        })),
        interactions: [],
      },
    ],
    direction: {
      rhythm: {
        leadInSeconds: 0,
        tailSeconds: 1,
        betweenActionsSeconds: 0,
        phaseScale: 1,
        clearSeconds: 1.6,
      },
      style: { renderer: 'reference-2d' },
      production: {
        version: '1.0.0',
        audio: {
          masterGain: 0.6,
          cues: [
            {
              eventType: 'block-crush-drop.piece-committed',
              assetId: 'builtin:soft-hit',
              gain: 0.5,
            },
            {
              eventType: 'block-crush-drop.blocks-eliminated',
              assetId: 'builtin:clear',
              gain: 0.45,
            },
          ],
        },
      },
    },
  });
}
